import csv, os
OUT = "/home/claude/emst/docs/research/private-sector"
V1 = "/home/claude/emst/data/v1_baseline/competencies.csv"
valid = {r["code"] for r in csv.DictReader(open(V1, encoding="utf-8"))}

def write(name, header, rows, codecol=None):
    with open(os.path.join(OUT, name), "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(header)
        for r in rows:
            assert len(r) == len(header), (name, r[0], len(r), len(header))
            if codecol is not None and r[codecol]:
                for c in r[codecol].split("|"):
                    assert c in valid, (name, r[0], c)
            w.writerow(r)
    print(name, len(rows))

